//"Pruebas Drum"
drive

samples('github:eddyflux/crate')
setcps(.75)


const DRUMS_G           =slider(0.554)
const SYNTH1_G          =slider(0.578)
const GTR_G             =slider(0.439)



const KICK              = s("bd").struct("<[x*<1 2> [~@3 x]] x>").gain(slider)
const SNARE             = s("~ [rim, sd:<2 3>]").room("<0 .2>")
const HAT               = n("[0 <1 3>]*<2!3 4>").s("hh")
const RIDE              = s("rd:<1!3 2>*2").mask("<0 0 1 1>/16").gain(.5)

const DRUMS  = stack(KICK, SNARE, HAT, RIDE).bank('crate').gain(DRUMS_G).color("#0055CF").punchcard()

const GTR1              =n("[48, 65]*<2!3 8>").s("gm_overdriven_guitar").slow(1).pan(0).gain(GTR_G).lpf(50000)
const GTR2              =n("[48, 65]*<2!3 8>").s("gm_distortion_guitar").slow(1).pan(1).gain(GTR_G).lpf(50000)
const SYNTH1            =n("c1 <eb1 <g1 g0>>").fastgap("<2!3 1>").partials(randL(6)).s("triangle").dist(1.4).hpf(250).jux(press).room(0.4).gain(SYNTH1_G).color("#3CDA82")._scope()

stack(DRUMS, SYNTH1, GTR1, GTR2)

