// "Bomber Assembler" @by Melkocore
setcps(90/60/4)
const cc = await midin('SMK25II Bluetooth')
const kb = await midikeys('SMK25II Bluetooth')

//MIXER//
const MASTER       = slider (0.905)
const DRUMS_G      = slider (0.719)
const BASSLINE1_G  = slider (0.442)
const KB_G         = slider (0.563)

//DRUMS//
const KICK        = s("bd").struct("x ~ x ~ x ~ x ~ ")
