//"midi microtonal"
setcpm(120/4/4)

const cc = await midin('Midi Through Port-0')
const kb = await midikeys('Midi Through Port-0')

const EDO = 31
const ROOT_MIDI = 60      // C4 como grado 0
const ROOT_HZ = 261.63    // frecuencia de C4

kb()
  .fmap(v => {
    const midiNum = typeof v === 'object' ? v.note : v
    const degree = midiNum - ROOT_MIDI  // grado relativo a la raíz
    const hz = ROOT_HZ * Math.pow(2, degree / EDO)
    return { ...v, freq: hz, note: undefined }
  }).s("juegos:2").gain(cc(30)).decay(2)

